export interface Plan { gb: number; days: number; price: string; code?: string; id?: string; slug?: string; isUnlimited?: boolean }
export interface PackageData {
  flag: string;
  country: string;
  countryCode: string; // ISO 2 hərli kodu (SVG loqolar üçün)
  slug: string;
  region: string;
  featured?: boolean;
  plans: Plan[];
}
export type PackageCategory = 'popular' | 'countries' | 'regional' | 'global';

export interface RegionalPackage {
  name: string;
  slug: string;
  flags: string[];
  countryCount: number;
  plans: Plan[];
}

function m(cost: number): string {
  return '$' + (cost * 1.75).toFixed(2);
}

